<?php
namespace App\Http\Requests;
use Illuminate\Foundation\Http\FormRequest;
class ScheduleMeetingRequest extends FormRequest { public function authorize(): bool { return $this->user()?->isActive() === true; } public function rules(): array { return ['meeting_date'=>['required','date'],'start_time'=>['required','date_format:H:i'],'duration_minutes'=>['required','integer','min:15','max:480'],'location'=>['required','string','max:255'],'chairperson_employee_id'=>['required','integer','exists:employees,id'],'participant_ids'=>['required','array','min:1'],'participant_ids.*'=>['integer','exists:employees,id']]; } public function messages(): array { return ['required'=>'وارد کردن :attribute الزامی است.','participant_ids.min'=>'حداقل یک اشتراک‌کننده باید انتخاب شود.']; } public function attributes(): array { return ['meeting_date'=>'تاریخ جلسه','start_time'=>'زمان آغاز','duration_minutes'=>'مدت جلسه','location'=>'محل جلسه','chairperson_employee_id'=>'رئیس جلسه','participant_ids'=>'اشتراک‌کنندگان نهایی']; } }